<?php require 'page-guard.php';if($_SESSION['user-role']!=='administrator'){http_response_code(403);exit('Administrators only.');}require '../config/db_conn.php';require 'components.php';$conn->query("CREATE TABLE IF NOT EXISTS sections (SECTION_ID INT AUTO_INCREMENT PRIMARY KEY, SECTION VARCHAR(80) NOT NULL UNIQUE)");$sections=$conn->query("SELECT SECTION FROM sections UNION SELECT DISTINCT SECTION FROM students WHERE SECTION IS NOT NULL AND SECTION<>'' ORDER BY SECTION");adminHead('Add teacher');adminSidebar('teachers','Add teacher','Create a teacher account for a selected section'); ?>
<section class="mx-auto max-w-2xl rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200 sm:p-8"><p class="text-sm font-bold uppercase tracking-widest text-blue-600">People & permissions</p><h2 class="mt-2 text-2xl font-black text-slate-900">Create teacher account</h2><p class="mt-2 text-slate-500">Teachers can view and export attendance for their assigned section.</p><form action="save-teacher.php" method="post" class="mt-7 space-y-5"><label class="block text-sm font-bold text-slate-700">Teacher name<input class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3" name="teacher_name" maxlength="120" required></label><label class="block text-sm font-bold text-slate-700">Email / username<input class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3" type="email" name="teacher_user" maxlength="100" required></label><div class="rounded-xl border border-slate-200 p-4"><p class="text-sm font-bold text-slate-700">Password</p><div class="mt-3 grid gap-4 sm:grid-cols-2"><label class="block text-sm font-semibold text-slate-600">Password<div class="relative"><input id="teacher-pass" class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3 pr-16" type="password" name="teacher_pass" minlength="8" required><button type="button" data-toggle="teacher-pass" class="absolute right-2 top-3 rounded-lg px-2 py-1 text-xs font-bold text-blue-600">Show</button></div></label><label class="block text-sm font-semibold text-slate-600">Confirm password<div class="relative"><input id="teacher-confirm" class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3 pr-16" type="password" name="teacher_confirm" minlength="8" required><button type="button" data-toggle="teacher-confirm" class="absolute right-2 top-3 rounded-lg px-2 py-1 text-xs font-bold text-blue-600">Show</button></div></label></div></div><label class="block text-sm font-bold text-slate-700">Assigned section<select class="mt-2 w-full rounded-xl border border-slate-300 bg-white px-4 py-3" name="section" required><option value="">Choose a section</option><?php while($s=$sections->fetch_assoc()): ?><option><?= htmlspecialchars($s['SECTION']) ?></option><?php endwhile; ?></select></label><button class="w-full rounded-xl bg-blue-600 px-5 py-3 font-bold text-white hover:bg-blue-700">Create teacher account</button></form></section><script>document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const i=document.getElementById(b.dataset.toggle);i.type=i.type==='password'?'text':'password';b.textContent=i.type==='password'?'Show':'Hide'});document.querySelector('form').onsubmit=e=>{if(document.getElementById('teacher-pass').value!==document.getElementById('teacher-confirm').value){e.preventDefault();alert('Passwords do not match.')}}</script><?php adminFoot(); ?>
